def load_products_processed_csv(**_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0357000" if __import__("os").path.isdir("./environment_mix/0357000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.utcnow()

    # Reject unexpected fields (this endpoint accepts no parameters)
    if _extra and len(_extra) > 0:
        # still log request below
        status = "error"
        err = _err("VALIDATION_ERROR", "This endpoint accepts no parameters.", unexpected_fields=sorted(list(_extra.keys())))
        # audit log
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
        except Exception:
            logs = []
        now = datetime.datetime.utcnow()
        latency_ms = int((now - started).total_seconds() * 1000)
        logs.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": "load_products_processed_csv",
            "timestamp": now.isoformat() + "Z",
            "status": status,
            "latency_ms": latency_ms
        })
        _save("request_log.json", logs)
        return err

    # Load products from the real datastore (products.json) rather than missing CSV
    products = _load("products.json")
    if isinstance(products, dict) and "rows" in products and isinstance(products.get("rows"), list):
        rows = products.get("rows", [])
    elif isinstance(products, list):
        rows = products
    else:
        rows = []

    # Normalize/validate row types best-effort (do not fabricate rows)
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        rr = dict(r)
        # Coerce known numeric fields when present; if coercion fails, keep original
        if "price" in rr:
            try:
                rr["price"] = float(rr["price"])
            except Exception:
                pass
        if "stock" in rr:
            try:
                rr["stock"] = int(rr["stock"])
            except Exception:
                pass
        out.append(rr)

    # audit log (every call)
    try:
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
    except Exception:
        logs = []
    now = datetime.datetime.utcnow()
    latency_ms = int((now - started).total_seconds() * 1000)
    logs.append({
        "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
        "endpoint": "load_products_processed_csv",
        "timestamp": now.isoformat() + "Z",
        "status": "ok",
        "latency_ms": latency_ms
    })
    _save("request_log.json", logs)

    return {
        "data": out,
        "meta": {
            "total": len(out),
            "has_more": False,
            "next_cursor": None
        }
    }

